package report

const workersHTML=`{{define "workers"}}{{if .Distribution}}{{$d:=.Distribution}}
<section class="panel" style="margin:22px 0"><h2>Distributed workers <span class="badge {{if not $d.Complete}}fail{{end}}">{{if $d.Complete}}COMPLETE{{else}}INCOMPLETE{{end}}</span></h2>
{{if not $d.Complete}}<div class="warning">{{$d.Failure}} Global metrics include only workers with final results. Missing worker traffic is unknown. {{n $d.UnreportedPlannedArrivals}} planned arrivals remain unreported; this can include work canceled before admission.</div>{{end}}
<div class="details"><span>{{n $d.PlannedArrivals}} planned {{.Workload}}</span><span>{{len $d.Workers}} workers · fleet concurrency {{.ConcurrencyLimit}}</span></div>
<div class="scroll"><table><thead><tr><th>Worker</th><th>Status</th><th>Capacity</th><th>Assigned arrivals</th><th>Reported arrivals</th><th>HTTP completed</th><th>CPU avg</th><th>Heap peak</th></tr></thead><tbody>
{{range $d.Workers}}<tr><td>{{.Name}}<div class="note">{{.URL}}</div></td><td>{{.Status}}{{if .Error}}<div class="note bad">{{.Error}}</div>{{end}}</td><td>{{.Capacity}}</td><td>{{n .Planned}}</td><td>{{if or (eq .Status "finished") (eq .Status "interrupted")}}{{if eq $.Workload "journeys"}}{{n .Journeys.Scheduled}}{{else}}{{n .Requests.Scheduled}}{{end}}{{else}}Unknown{{end}}</td><td>{{if or (eq .Status "finished") (eq .Status "interrupted")}}{{n .Requests.Completed}}{{else}}Unknown{{end}}</td><td>{{if .Generator}}{{if .Generator.CPUAvailable}}{{f .Generator.AverageCPUPercent}}%{{else}}Unavailable{{end}}{{else}}—{{end}}</td><td>{{if .Generator}}{{mib .Generator.PeakHeapBytes}} MiB{{else}}—{{end}}</td></tr>{{end}}
</tbody></table></div><div class="details">{{range $d.Workers}}<span>{{.Name}} · clock offset {{f .ClockOffsetMS}} ms · probe RTT {{f .RoundTripMS}} ms{{if .Generator}} · {{.Generator.Platform}} · {{.Generator.GoVersion}}{{end}}</span>{{end}}</div>
<p class="small">Percentiles merge histogram buckets before evaluation; worker percentiles are not averaged. CPU and heap belong to each worker process. In-flight peaks sum worker peaks and are an upper bound, not an observed simultaneous peak. Rates and concurrency are fleet totals; capacity is reserved per worker. Clock probes estimate offset but cannot eliminate asymmetric network delay. Total wall time includes result collection.</p></section>{{end}}{{end}}`
